with latest as (select * from stores qualify row_number() over (partition by region order by sqft, id) = 1) select city, case when sqft >= 17534 then 'LARGE' else 'SMALL' end as sqft_tier, bit_or(sqft) as sqft_bit_or, sum(case when region = 'West' then sqft else 0 end) as west_sqft, round(avg(sqft), 2) as avg_sqft, count(*) as num_rows, max(sqft) as max_sqft from latest group by city, sqft_tier order by avg_sqft desc
